window.bongaTaskAgenda=(tasks,area='all',view='open')=>{const date=value=>{if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value))return '9999-99-99';const d=new Date(value+'T12:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value?value:'9999-99-99';},priority={high:0,medium:1,low:2};return tasks.filter(t=>(area==='all'||t.area===area)&&(view==='all'||(view==='completed'?!!t.done:!t.done))).sort((a,b)=>Number(!!a.done)-Number(!!b.done)||date(a.due).localeCompare(date(b.due))||(priority[a.priority]??1)-(priority[b.priority]??1));};
